import { createRouter, createWebHashHistory } from 'vue-router'
// import HomeView from '../views/HomeView.vue'

const routes = [
  {
    path: '/',
    name: 'home',
    // component: HomeView,
    component: () => import('../views/HomeView.vue'),
    children: [
      {
        path: '',
        name: 'main',
        component: () => import('../views/MainPage.vue')
      },
      {
        path: 'about',
        name: 'about',
        component: () => import('../views/AboutBrand.vue')
      },
      {
        path: 'shop',
        name: 'shop',
        component: () => import('../views/PDShop.vue')
      },
      {
        path: 'gallery',
        name: 'gallery',
        component: () => import('../views/PDGallery.vue'),
        children: [
          // 相同結構的頁面可共用結構 .vue 檔案，分別塞入不同元件
          {
            path: 'living',
            components: {
              up: () => import('../components/GalleryLiving.vue'), // 屬性為 router-view 的 name
              down: () => import('../components/GridWaterfallLiving.vue')
            }
          },
          {
            path: 'dining',
            components: {
              up: () => import('../components/GalleryDining.vue'),
              down: () => import('../components/GridWaterfallDining.vue')
            }
          },
          {
            path: 'study',
            components: {
              up: () => import('../components/GalleryStudy.vue'),
              down: () => import('../components/GridWaterfallStudy.vue')
            }
          },
          {
            path: 'work',
            components: {
              up: () => import('../components/GalleryWork.vue'),
              down: () => import('../components/GridWaterfallWork.vue')
            }
          }
        ]
      },
      {
        path: 'FAQ',
        name: 'FAQ',
        component: () => import('../views/FAQPage.vue')
      },
      {
        path: 'cart',
        name: 'cart',
        component: () => import('../views/UserCartlist.vue')
      },
      {
        path: 'checkout',
        name: 'checkout',
        component: () => import('../views/UserCheckout.vue')
      },
      {
        path: 'paying/:orderId',
        name: 'paying',
        component: () => import('../views/UserPay.vue')
      },
      {
        path: 'finished',
        name: 'finished',
        component: () => import('../views/UserFinish.vue')
      },
      {
        path: 'like',
        name: 'like',
        component: () => import('../views/LikelistPage.vue')
      }
    ]
  },
  {
    path: '/login',
    name: 'login',
    component: () => import('../views/AdminLogin.vue')
  },
  {
    path: '/admin',
    name: 'admin',
    component: () => import('../views/AdminDashboard.vue'),
    children: [
      {
        path: '',
        name: 'adminProduct',
        component: () => import('../views/AdminProduct.vue')
      },
      {
        path: 'order',
        name: 'order',
        component: () => import('../views/AdminOrder.vue')
      },
      {
        path: 'coupon',
        name: 'coupon',
        component: () => import('../views/AdminCoupon.vue')
      }
    ]
  },
  {
    path: '/product',
    name: 'userProduct',
    component: () => import('../views/HomeView.vue'),
    children: [
      {
        path: ':productId(.*)', // 單一商品頁使用動態路由
        name: 'product',
        component: () => import('../views/PDDetail.vue')
      }
    ]
  },
  // 404 頁面：須放在最後方，如果不匹配上方任何路由顯示
  {
    path: '/:pathMatch(.*)*', // .* 所有子路徑、 * 所有頁面 ( . 代表任意字元 / * 代表 0 個或多個以上)
    name: 'notfound',
    component: () => import('../views/NotFound.vue')
  }
]

const router = createRouter({
  history: createWebHashHistory(),
  routes,

  // 高亮：當前項目加上 class 名稱
  linkActiveClass: '', // 預設為 router-link-active，模糊比對
  linkExactActiveClass: 'active', // 預設為 router-link-exact-active，嚴格匹配(當有 path:'' 的頁面選到它的 children 不會同時高亮)

  // 換頁回到最上方
  scrollBehavior(to, from, savedPosition) {
    // console.log(to, from, savedPosition) // to 前往頁面、from 來自頁面、視窗位置(未存取顯示 null)
    // 當網址路徑含有 '/' 的頁面有 scrollTop
    if (to.fullPath.match('/')) {
      return {
        top: 0,
        left: 0,
        behavior: 'instant' // 'instant' 表示瞬間切換，無平滑效果
      }
    }
    return {}
  }
})

export default router
